  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Reject; counter at 25%."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reject all three elements."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Reject; hold 24 months."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Insist on a 100% cap, at least 6 years, and exclusion from the basket, de minimis and knowledge bar."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Insert an express carve-out covering the Seller, its officers, employees and advisers. Do not offer this point as a trade."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject. Delete 1.1 and 1.2."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject. Delete 8.3."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Bluefen: effective consent plus evidence of clause 11.3 conditions as a Condition Precedent, not reasonable endeavours or consent-on-delivery."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Reject the post-completion release."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "DD-005 bonuses (AUD 420k plus on-costs): a specific funds-flow line or express Seller funding, with an indemnity."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Broaden the Ironquay indemnity, preserve the SOW3 cure, and verify the AUD 180k independently."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "DD-006: preservation, investigation and update covenants. Assume no breach or loss either way, and strike \"not expected to be material\"."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Sandbar: request information before deciding treatment. No automatic deduction, and no acceptance of \"ordinary course\"."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reverse the default: general limitations apply only to general Warranty Claims, and each other regime is stated expressly."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Title: require independent title, encumbrance and authority evidence beyond DD-012."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not concede general-regime treatment. Do not assume either party has agreed unlimited liability."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

